        valid = permitted and resolved.is_file()
        line_count = None
        if valid:
            line_count = len(read(resolved).splitlines())
            if fragment:
                match = re.fullmatch(r'L(\d+)', fragment)
                valid = bool(match) and 1 <= int(match.group(1)) <= line_count
        row = {'document': relative, 'target': target, 'permitted_target': permitted, 'line_count': line_count, 'valid': valid}
        links.append(row)
        if not valid:
            failures.append({'check': 'markdown_link', **row})
required = ['A rejected payment can be retried with its original payment reference.', 'Repeating an accepted reference must not create a second payment.', 'Late-arrival retention duration remains unresolved. The source provides no default.']
clauses = [{'clause': clause, 'present': clause in texts['tasks/recovery-draft.md']} for clause in required]
for clause in clauses:
    if not clause['present']:
        failures.append({'check': 'draft_clause', **clause})
result = {'status': 'PASSED' if not failures else 'FAILED', 'protected_inputs': protected, 'links': links, 'clauses': clauses, 'failures': failures, 'files_read': read_paths, 'files_written': []}
print(json.dumps(result))
raise SystemExit(0 if not failures else 1)
